p=Path('styles.css');s=p.read_text(encoding='utf-8');s+='''
/* Dedicated opening artwork, layered original starter sprites and a simple game logo. */
.adventure-title{width:min(1160px,100%);height:min(740px,calc(100svh - 36px));min-height:0;isolation:isolate;border:3px solid #dce6b7;outline:1px solid #6d9871;border-radius:30px;background:#88b8a3;box-shadow:0 16px 60px #102a224d,inset 0 0 0 5px #fff2cd55}.title-backdrop{position:absolute;inset:0;z-index:-3;background:url('assets/world/title-adventure.png') center center/cover no-repeat}.title-vignette{position:absolute;inset:0;z-index:-2;pointer-events:none;background:linear-gradient(180deg,#e7fff022 0%,transparent 40%,#163e3326 70%,#143f36b3 100%);box-shadow:inset 0 0 80px #153c2d26}.game-logo{position:absolute;top:42px;left:12px;right:12px;margin:0;display:flex;align-items:center;flex-direction:column;gap:6px;z-index:2;line-height:1.1}.game-logo small{font-size:23px;font-weight:400;letter-spacing:7px;color:#fff4cd;background:#3a6d548c;border:1px solid #fff0bb99;border-radius:30px;padding:8px 19px 8px 26px;text-shadow:0 2px #294c3d;box-shadow:0 4px 15px #456b3e22}.game-logo>span{font-size:88px;letter-spacing:6px;color:#fff1ad;-webkit-text-stroke:5px #356647;paint-order:stroke fill;text-shadow:0 6px 0 #2f5a3f,0 10px 0 #264a3633,0 12px 25px #193b2840;transform:rotate(-2deg)}.adventure-title .title-pokemon{position:absolute;left:50%;right:auto;bottom:130px;transform:translateX(-50%);width:540px;max-width:85%;align-items:flex-end;justify-content:center;gap:4px;z-index:2}.adventure-title .title-pokemon>span{position:relative;width:33%;display:grid;place-items:center}.adventure-title .title-pokemon>span:before{content:'';position:absolute;width:57%;height:14%;bottom:8%;border-radius:50%;background:#244b3766;filter:blur(3px)}.adventure-title .title-pokemon img{position:relative;width:100%;height:auto;image-rendering:pixelated;filter:drop-shadow(0 5px 0 #244d3526);transform-origin:50% 90%;animation:starter-sway 4.8s ease-in-out infinite}.adventure-title .title-pokemon>span:nth-child(2){margin-bottom:12px}.adventure-title .title-pokemon>span:nth-child(2) img{animation-delay:-1.5s}.adventure-title .title-pokemon>span:nth-child(3) img{animation-delay:-3s}.adventure-title .start-game{bottom:42px;display:flex;align-items:center;gap:20px;min-width:280px;justify-content:center;line-height:1;font-size:26px;padding:19px 27px;background:linear-gradient(#fff4ce,#e9dfa7);color:#315d43;border:2px solid #fff7e1;border-radius:18px;box-shadow:0 6px 0 #2c5843,0 10px 24px #163a3455;transition:transform .2s,box-shadow .2s}.adventure-title .start-game:hover{background:#fff8dc;transform:translateY(-3px);box-shadow:0 9px 0 #2c5843,0 13px 26px #163a3455}.adventure-title .start-game:active{transform:translateY(3px);box-shadow:0 3px 0 #2c5843}.start-arrow{font-size:14px;color:#578565}.start-icon{width:22px;height:22px;border:2px solid #5a7759;border-radius:50%;background:linear-gradient(#d78b67 0 43%,#5a7759 43% 56%,#fff4d6 56%);position:relative}.start-icon:after{content:'';position:absolute;width:6px;height:6px;border:2px solid #5a7759;border-radius:50%;background:#fff3d2;left:4px;top:5px}.title-motes{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:1}.title-motes i{position:absolute;left:var(--x);top:var(--y);width:4px;height:4px;border-radius:50%;background:#fff2ac;box-shadow:0 0 9px 3px #fff2ac66;animation:title-mote 6s ease-in-out infinite;animation-delay:var(--delay)}@keyframes title-mote{0%,100%{opacity:.15;transform:translate(0,8px)}50%{opacity:.9;transform:translate(var(--drift),-15px)}}@keyframes starter-sway{0%,100%{transform:translateY(0) rotate(-1deg)}50%{transform:translateY(-5px) rotate(1deg)}}@media(max-width:700px){.adventure-title{height:calc(100svh - 36px);min-height:420px;border-radius:24px}.adventure-title .title-backdrop{background-position:49% center}.game-logo{top:12%;gap:12px}.game-logo small{font-size:18px;letter-spacing:5px;padding:7px 14px 7px 19px}.game-logo>span{font-size:clamp(48px,13vw,78px);letter-spacing:2px;-webkit-text-stroke:4px #356647}.adventure-title .title-pokemon{max-width:96%;bottom:145px;gap:0}.adventure-title .title-pokemon img{width:100%;max-width:160px}.adventure-title .start-game{bottom:55px;min-width:245px;font-size:24px;gap:16px;padding:17px 23px}}@media(max-height:540px) and (min-width:701px){.game-logo{top:16px;gap:0}.game-logo small{font-size:17px}.game-logo>span{font-size:60px}.adventure-title .title-pokemon{width:370px;bottom:94px}.adventure-title .start-game{bottom:22px;font-size:22px;padding:14px 25px}}@media(prefers-reduced-motion:reduce){.adventure-title .title-pokemon img,.title-motes i{animation:none}.adventure-title .start-game{transition:none}}
''';p.write_text(s,encoding='utf-8')
